SELECT CAST(("collect_datetime" + INTERVAL '9 hours') AS DATE) AS "day", "vehicle_id" AS "vehicle_id", (MAX("uman_time") - MIN("uman_time")) AS "uman_hours", ((MAX("eg_time") - MIN("eg_time")) - (MAX("uman_time") - MIN("uman_time"))) AS "manned_hours" FROM "bms_log" WHERE "collect_datetime" >= (TIMESTAMP '2026-10-15 00:00:00' - INTERVAL '9 hours') AND "collect_datetime" < (TIMESTAMP '2026-10-20 00:00:00' - INTERVAL '9 hours') GROUP BY CAST(("collect_datetime" + INTERVAL '9 hours') AS DATE), "vehicle_id"